import logging


class Config(object):
    def __init__(self):
        self.config = {}
        self.logger = logging.getLogger(__name__)

    def join_values(self, value):
        return ",".join(map(self.join_values_helper, value))

    def join_values_helper(self, x):
        return ",".join(map(self.join_values_helper_2, x))

    def join_values_helper_2(self, y):
        return ",".join(map(self.join_values_helper_3, y))

    def join_values_helper_3(self, z):
        return ",".join(map(str, z))

    def set_config_dict_dict_dict_dict_int(self, section, key, value):
        self.config[section][key] = self.join_values(value)
        self.logger.info("Config: " + str(self.config))


def run(value):
    """Stores value in the configuration and returns the stored text. Public entry point of this unit."""
    config = Config()
    config.config["world"] = {}
    config.set_config_dict_dict_dict_dict_int("world", "regions", value)
    return config.config["world"]["regions"]
```

